head.script:
scwin.gVar = {
    "cDisabled" : "",
}



// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[secret > P > disabled]<br/>Secret 컴포넌트의 비활성화(disabled) 상태를 설정합니다.",
    "validation" : [
        "true 설정 시, 컴포넌트를 비활성화(disabled) 상태로 설정합니다.",
        "true 설정 시, 컴포넌트에 'w2input_disabled' 클래스가 추가됩니다.",
        "false 설정 시, 컴포넌트의 비활성화(disabled) 상태를 해제합니다.",
        "미설정 시, 컴포넌트의 비활성화(disabled) 상태를 해제합니다.",
        "컴포넌트가 비활성화(disabled) 상태이면 클릭, 툴팁, 포커스, 입력, 이벤트 등과 같은 상호작용이 발생하지 않습니다.",
        "컴포넌트를 읽기 전용(readonly) 상태로 설정하려면 readOnly 속성을 사용하여야 합니다.",
        "컴포넌트가 비활성화(disabled) 상태일때 입력값 복사는 표준 동작은 아니지만 최신 웹브라우저에서 지원하고 있습니다.",
    ]
}



scwin.wf_sample_onwframeload = function () {
    let wf_body_left = wf_sample.getObj("wf_body_left");
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 컴포넌트 있으면 삭제
    if (typeof label1 !== 'undefined') {
        label1.remove();
    }

    if (typeof input_prev !== 'undefined') {
        input_prev.remove();
    }

    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    if (typeof input_paste !== 'undefined') {
        input_paste.remove();
    }

    $c.gcm.createLabel('label="[전제] target1 은 Secret 컴포넌트(초기값 secret), 위 input_prev 는 Tab 출발점, 아래 input_paste 는 붙여넣기 확인용\n[절차] disabled 값 선택 후 Target 재생성 -> target1 클릭 / 마우스 오버 / input_prev 에서 Tab 키 / target1 에 키 입력 / target1 값 선택 후 Ctrl+C 하여 input_paste 에 Ctrl+V\n[확인] 재생성 시 출력되는 class 와 disabled / readonly 속성값, 결과창의 이벤트 발생 여부, 툴팁 표시 여부, 붙여넣기 영역의 값"', '', 'label1');

    // Tab 이동 출발점
    await $c.gcm.createBasicInput('', '', 'input_prev');

    // 조건 설정
    let properties = {
        disabled : scwin.gVar["cDisabled"],
        tooltip : "secret tooltip",
    }

    let cList = $c.gcm.createCList(properties)

    let eList = $c.gcm.createEList(["onclick", "onfocus", "onkeydown"])

    // comp 생성 함수 호출
    await $c.gcm.createBasicSecret(cList, eList);

    // 붙여넣기 확인용 (빈 값)
    let cListPaste = $c.gcm.createCList({ style : "width:200px; height:30px;" })

    await $c.gcm.createEmptyInput(cListPaste, '', 'input_paste');

    scwin.printCompState();
}



// validation 1, 2, 3, 4, 6 판정 출력
scwin.printCompState = function () {
    let objInput = target1.render;
    let strDisabled = (scwin.gVar["cDisabled"] === "") ? "미설정" : scwin.gVar["cDisabled"];

    wf_sample.getObj("wf_body_bottom").getObj("scwin").setReturnValue("disabled " + strDisabled + " -> class : " + objInput.className + " / disabled 속성 : " + objInput.hasAttribute("disabled") + " / readonly 속성 : " + objInput.hasAttribute("readonly"));
}



// 테스트 샘플의 이벤트 처리 (키 입력) - validation 5 판정 출력
scwin.target1_onkeydown = function (e) {
    wf_sample.getObj("wf_body_bottom").getObj("scwin").setReturnValue("=====target1_onkeydown 이벤트 발생=====");
}
